public class InvocationMatcher_hasSameMethod_TriageGen1Test {

    @Test
    public void testHasSameMethod_ReturnsTrueWhenMethodsAreEqual() throws NoSuchMethodException {
        // Arrange
        Method method = String.class.getMethod("length");

        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(method);

        InvocationMatcher matcher = new InvocationMatcher(invocation);

        Invocation candidate = mock(Invocation.class);
        when(candidate.getMethod()).thenReturn(method);

        // Act
        boolean result = matcher.hasSameMethod(candidate);

        // Assert
        assertTrue(result);
    }

    @Test
    public void testHasSameMethod_ReturnsFalseWhenMethodsAreDifferent() throws NoSuchMethodException {
        // Arrange
        Method method1 = String.class.getMethod("length");
        Method method2 = String.class.getMethod("isEmpty");

        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(method1);

        InvocationMatcher matcher = new InvocationMatcher(invocation);

        Invocation candidate = mock(Invocation.class);
        when(candidate.getMethod()).thenReturn(method2);

        // Act
        boolean result = matcher.hasSameMethod(candidate);

        // Assert
        assertFalse(result);
    }

